class DualMomentum(Strategy):
    name = "dual_momentum"
    SHORT = 60
    LONG = 250
    warmup_bars = 260

    def on_bar(self, symbol, store):
        window = store.window(symbol, self.timeframe)
        if len(window) < self.warmup_bars:
            return math.nan
        closes = window.closes()
        # log returns
        log_ret = np.diff(np.log(closes))
        short = ta.sma(log_ret, self.SHORT)
        long = ta.sma(log_ret, self.LONG)
        if not (math.isfinite(short) and math.isfinite(long)):
            return math.nan
        if short > long:
            return 1.0
        else:
            return -1.0
